using System;using System.IO;using System.Reflection;using System.Collections;
class Test52Library {
 static int n;static void Check(bool ok,string why){if(!ok)throw new Exception(why);n++;}
 static void Main(){var a=Assembly.LoadFrom("MedianGrassReplacement.dll");var type=a.GetType("MedianGrassReplacement.SurfaceTextureCatalog");var f=BindingFlags.Static|BindingFlags.NonPublic;var method=type.GetMethod("LibraryFiles",f);var label=type.GetMethod("LibraryLabel",f);string parent=Path.GetFullPath(Directory.GetCurrentDirectory()),root=Path.Combine(parent,"library-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string nested=Path.Combine(root,"pack","textures");Directory.CreateDirectory(nested);File.WriteAllText(Path.Combine(root,"surface.png"),"fixture");File.WriteAllText(Path.Combine(nested,"surface.png"),"fixture");int count=0;foreach(string file in (IEnumerable)method.Invoke(null,new object[]{root}))count++;Check(count==2,"root and nested pack PNG discovered");Check((string)label.Invoke(null,new object[]{root,Path.Combine(root,"surface.png")})!=(string)label.Invoke(null,new object[]{root,Path.Combine(nested,"surface.png")}),"same-name files in packs receive distinct labels");string deep=Path.Combine(nested,"too-deep");Directory.CreateDirectory(deep);File.WriteAllText(Path.Combine(deep,"ignored.png"),"fixture");count=0;foreach(string file in (IEnumerable)method.Invoke(null,new object[]{root}))count++;Check(count==2,"scan remains bounded to supported folder depth");for(int i=0;i<270;i++)File.WriteAllText(Path.Combine(root,i+".png"),"fixture");count=0;foreach(string file in (IEnumerable)method.Invoke(null,new object[]{root}))count++;Check(count==256,"visible catalog remains bounded");}finally{string target=Path.GetFullPath(root);if(target.StartsWith(parent+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(target,true);}Console.WriteLine(n+" nested texture-library discovery, naming and scan-bound checks passed.");}}
